#!/usr/bin/env bash
# CF-247 Website API v2 R23/R24 on an isolated PostgreSQL (never a Supabase project): PGHOST/PGPORT/PGUSER point at a scratch server.
#  1. builds a throwaway database with the production shape: roles and schemas, the live schema dump of the 45 relations involved
#     (schema-prod.sql, generated by gen-schema.py from supabase/live-capture/baseline/schema.sql) brought to 5 Nov 2026 by
#     schema-live-patch.sql, the 18 live function definitions in live/ and their live privileges (function-grants.sql);
#  2. proves parity with live: the fingerprint of every relation (columns, constraints, foreign keys, indexes, triggers, row level security,
#     grants, view text) equals parity-live-2026-11-09.txt, and every function's md5 and privileges equal functions-live.tsv;
#  3. seeds synthetic records through those constraints and triggers (seed.sql) and snapshots the live output (before.sql);
#  4. shows the migration REFUSES without the Platform Admin's approval setting and changes nothing;
#  5. records the approval setting as the approval paste would, shows the migration REFUSES to re-take the consumer baseline while an unrelated
#     consumer function differs from it, applies the migration unchanged (md5 guards, after-md5 checks, baseline re-taken with only the two
#     approved functions changed), applies it again (already applied, unchanged), and runs every check (fixtures.sql), builders and end to end
#     as service_role;
#  6. benchmarks the live and new definitions side by side on a volume dataset (bench.sql); A_BENCH_OUT keeps the figures.
# Drops the throwaway database at the end unless A_KEEP is set.
set -euo pipefail
cd "$(dirname "$0")"
DB=${A_R2324_DB:-a_r2324_fixture}
MIG=../../../supabase/migrations/20261109150000_cf247_website_api_v2_r23_r24.sql
P="psql -v ON_ERROR_STOP=1 -q -X"
$P -d postgres -c "drop database if exists $DB" -c "create database $DB" >/dev/null
[ -n "${A_KEEP:-}" ] || trap '$P -d postgres -c "drop database if exists $DB" >/dev/null' EXIT
show() { sed -n 's/^.*\(NOTICE\|ERROR\):  /\1 /p'; }
md5of() { $P -d $DB -Atc "select md5(pg_get_functiondef('$1'::regprocedure))"; }
$P -d $DB -f roles-schemas.sql -f schema-prod.sql 2>&1 | grep -v '^NOTICE' || true
for f in live/*.sql; do $P -d $DB -c "set check_function_bodies = off" -f "$f"; done
$P -d $DB -f schema-live-patch.sql -f function-grants.sql
# parity with live
$P -d $DB -A -F'|' -f check-live-parity.sql | sed '$d' > /tmp/a_r2324_parity.$$
diff parity-live-2026-11-09.txt /tmp/a_r2324_parity.$$ || { echo "fixture schema differs from live (above)"; rm -f /tmp/a_r2324_parity.$$; exit 1; }
rm -f /tmp/a_r2324_parity.$$
while IFS=$'\t' read -r sig m acl; do
  got=$($P -d $DB -Atc "select md5(pg_get_functiondef('$sig'::regprocedure)) || E'\t' || coalesce(replace(array_to_string(proacl, ','), 'm/', '/'), '(default)') from pg_proc where oid = '$sig'::regprocedure")
  [ "$got" = "$m"$'\t'"$acl" ] || { echo "$sig differs from live: $got (live $m $acl)"; exit 1; }
done < functions-live.tsv
echo "parity: 45 relations and $(wc -l < functions-live.tsv) functions equal live (live re-check 9 Nov 2026)"
$P -d $DB -f seed.sql
$P -d $DB -f before.sql 2>&1 | show
# the consumer API baseline objects, taken from the real guard migration (table, function lists, re-baseline), and the baseline as of "before"
GUARD=../../../supabase/migrations/20261018050000_cf247_consumer_api_guard.sql
{ sed -n '/^create table if not exists pipeline.consumer_api_baseline/,/^alter table pipeline.consumer_api_baseline enable/p' $GUARD
  sed -n '/^create or replace function security.consumer_api_functions_v1/,/^\$function\$;/p' $GUARD
  sed -n '/^create or replace function security.consumer_api_relations_v1/,/^\$function\$;/p' $GUARD
  sed -n '/^create or replace function security.consumer_api_rebaseline_v1/,/^end \$function\$;/p' $GUARD; } | $P -d $DB
$P -d $DB -Atc "select security.consumer_api_rebaseline_v1('fixture: the consumer API as found before R23/R24')" >/dev/null
BASE0=$($P -d $DB -Atc "select md5(string_agg(name || ' ' || md5, ',' order by name)) from pipeline.consumer_api_baseline where kind = 'function' and name not in ('api.website_v2_provider_campuses(uuid)', 'api.website_v2_scholarship_item(uuid)')")
# without approval the migration refuses and changes nothing
if OUT=$($P -d $DB -1 -At -f $MIG 2>&1); then echo "the migration applied without approval"; exit 1; fi
echo "$OUT" | grep -q 'setting api.v2_r23_r24_approved is not 1' || { echo "refusal message missing: $OUT"; exit 1; }
[ "$(md5of 'api.website_v2_provider_campuses(uuid)')" = 57115d3b8ddbc40729ec04078ee15d41 ] && [ "$(md5of 'api.website_v2_scholarship_item(uuid)')" = d1792cc7161101ce8c22abad70ecbd36 ] || { echo "a refused run changed a definition"; exit 1; }
echo "no approval: refused, nothing changed"
# approval recorded: the Platform Admin's approval paste itself (approval-setting.sql; approval package §9)
$P -d $DB -f approval-setting.sql
# an unrelated consumer function that differs from the baseline: the migration refuses and changes nothing (the baseline is never re-taken over it)
$P -d $DB -c "alter function api.website_text_array(jsonb) set work_mem = '64MB'"
if OUT=$($P -d $DB -1 -At -f $MIG 2>&1); then echo "the migration applied over an unrelated consumer API difference"; exit 1; fi
echo "$OUT" | grep -q 'other than the two approved functions differ from the baseline (\["api.website_text_array(jsonb)"\])' || { echo "drift refusal missing: $OUT"; exit 1; }
[ "$(md5of 'api.website_v2_provider_campuses(uuid)')" = 57115d3b8ddbc40729ec04078ee15d41 ] && [ "$(md5of 'api.website_v2_scholarship_item(uuid)')" = d1792cc7161101ce8c22abad70ecbd36 ] || { echo "a refused run changed a definition"; exit 1; }
$P -d $DB -c "alter function api.website_text_array(jsonb) reset work_mem"
[ "$(md5of 'api.website_text_array(jsonb)')" = fb1fbe6030a95e2c6db38e34ccf86850 ] || { echo "the drift was not undone"; exit 1; }
echo "unrelated consumer API difference: refused, nothing changed"
$P -d $DB -1 -At -f $MIG | grep -c ': applied' | grep -qx 2 || { echo "the migration did not apply both guarded changes"; exit 1; }
A1=$(md5of 'api.website_v2_provider_campuses(uuid)'); A2=$(md5of 'api.website_v2_scholarship_item(uuid)')
echo "after: website_v2_provider_campuses $A1, website_v2_scholarship_item $A2"
# the baseline now holds the two new definitions and every other consumer function exactly as before; live (checked as the guard checks) equals it
BASE1=$($P -d $DB -Atc "select md5(string_agg(name || ' ' || md5, ',' order by name)) from pipeline.consumer_api_baseline where kind = 'function' and name not in ('api.website_v2_provider_campuses(uuid)', 'api.website_v2_scholarship_item(uuid)')")
[ "$BASE0" = "$BASE1" ] || { echo "the re-take changed a consumer function other than the two approved ones"; exit 1; }
[ "$($P -d $DB -Atc "select count(*) from pipeline.consumer_api_baseline where kind = 'function' and ((name = 'api.website_v2_provider_campuses(uuid)' and md5 = '$A1') or (name = 'api.website_v2_scholarship_item(uuid)' and md5 = '$A2')) and reason like 'R23/R24%approved Platform Admin (Mandeep Singh) 9 Nov 2026'")" = 2 ] || { echo "the baseline does not hold the two new definitions"; exit 1; }
[ "$($P -d $DB -Atc "set search_path = ''; select count(*) from security.consumer_api_functions_v1() f join pipeline.consumer_api_baseline b on b.kind = 'function' and b.name = f.name where b.md5 is distinct from pg_catalog.md5(pg_catalog.pg_get_functiondef(f.oid))" | tail -1)" = 0 ] || { echo "live differs from the re-taken baseline"; exit 1; }
echo "baseline re-taken: the two approved functions changed, no other consumer function differs from it"
for s in 'api.website_v2_provider_campuses(uuid)' 'api.website_v2_scholarship_item(uuid)'; do
  [ "$($P -d $DB -Atc "select array_to_string(proacl, ',') from pg_proc where oid = '$s'::regprocedure")" = 'postgres=X/postgres' ] || { echo "$s privileges changed"; exit 1; }
done
$P -d $DB -1 -At -f $MIG 2>/dev/null | grep -c 'already applied' | grep -qx 2 || { echo "a second run changed something"; exit 1; }
[ "$(md5of 'api.website_v2_provider_campuses(uuid)')" = "$A1" ] && [ "$(md5of 'api.website_v2_scholarship_item(uuid)')" = "$A2" ] || { echo "a second run changed a definition"; exit 1; }
echo "second run: already applied, unchanged; privileges unchanged"
$P -d $DB -f fixtures.sql 2>&1 | show
# benchmark: the live definitions copied as fx.old_* beside the new ones
sed 's/api\.website_v2_provider_campuses(/fx.old_provider_campuses(/' live/website_v2_provider_campuses.sql | $P -d $DB
sed 's/api\.website_v2_scholarship_item(/fx.old_scholarship_item(/' live/website_v2_scholarship_item.sql | $P -d $DB
$P -d $DB -f bench.sql 2>&1 | sed -n 's/^.*NOTICE:  //p' | tee "${A_BENCH_OUT:-/dev/null}"
echo "all fixture checks passed"
